//! Small shared helpers: quoting, doc comments, identifiers and package segments.

use veld_codegen::naming::{self, Lang};
use veld_codegen::{CodeWriter, FileSet, GenDiagnostic};
use veld_ir::Decl;

/// First line of every generated file.
pub const HEADER: &str = "// Code generated by veld. DO NOT EDIT.";

/// Simple names the generated code relies on. A declaration with one of these names gets a
/// trailing `_` so it can never shadow (or be shadowed by) an import.
const TYPE_HAZARDS: &[&str] = &[
    "ApiKeyAuth",
    "Arrays",
    "BasicAuth",
    "BearerAuth",
    "BigDecimal",
    "Boolean",
    "Byte",
    "Character",
    "Class",
    "ClientCore",
    "ClientDefaults",
    "ClientOptions",
    "Codec",
    "Collections",
    "Comparable",
    "Constants",
    "Data",
    "Deprecated",
    "Double",
    "EndpointSpec",
    "Enum",
    "Error",
    "Exception",
    "Float",
    "HandlerHooks",
    "Instant",
    "Integer",
    "Issue",
    "Iterable",
    "Json",
    "LinkedHashMap",
    "List",
    "LocalDate",
    "LocalTime",
    "Long",
    "Map",
    "Math",
    "Number",
    "Object",
    "Objects",
    "Optional",
    "Override",
    "Page",
    "Record",
    "RequestContext",
    "Router",
    "Runnable",
    "Schema",
    "ServerEndpoint",
    "Short",
    "String",
    "StringBuilder",
    "SuppressWarnings",
    "System",
    "Thread",
    "Throwable",
    "UUID",
    "UntypedError",
    "Veld",
    "VeldError",
    "VeldHandler",
    "VeldHttpError",
    "VeldRequest",
    "VeldResponse",
    "VeldTransportError",
    "Void",
    "Wire",
];

/// Names (beyond the `Object` methods that `naming::member` escapes) a record component or
/// method must not take: they would clash with members the generator adds.
const MEMBER_HAZARDS: &[&str] = &[
    "codec",
    "data",
    "fromWire",
    "toWire",
    "veldCanonical",
    "veldOp",
    "wire",
];

/// A Java string literal. Everything outside printable ASCII becomes a `\uXXXX` escape, so the
/// output does not depend on the compiler's source encoding.
#[must_use]
pub fn java_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            ' '..='~' => out.push(c),
            c => {
                let mut units = [0u16; 2];
                for u in c.encode_utf16(&mut units) {
                    out.push_str(&format!("\\u{u:04x}"));
                }
            }
        }
    }
    out.push('"');
    out
}

/// The Java type name of a declaration (reserved words and hazards escaped).
#[must_use]
pub fn type_name(d: &Decl) -> String {
    let name = naming::escape(Lang::Java, &d.name);
    if TYPE_HAZARDS.contains(&name.as_str()) {
        format!("{name}_")
    } else {
        name
    }
}

/// A camelCase member (component, method, parameter) name that is safe in Java.
#[must_use]
pub fn member_ident(name: &str) -> String {
    let id = naming::camel(name);
    let id = if id.is_empty() { "_".to_string() } else { id };
    let id = naming::member(Lang::Java, &id);
    if MEMBER_HAZARDS.contains(&id.as_str()) {
        format!("{id}_")
    } else {
        id
    }
}

/// Makes `names` unique by appending `_` to later duplicates, keeping the order.
#[must_use]
pub fn unique(names: Vec<String>) -> Vec<String> {
    let mut out: Vec<String> = Vec::with_capacity(names.len());
    for mut n in names {
        while out.contains(&n) {
            n.push('_');
        }
        out.push(n);
    }
    out
}

/// A lower-case Java package segment derived from a name.
#[must_use]
pub fn segment(s: &str) -> String {
    let mut out: String = s
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_lowercase()
            } else {
                '_'
            }
        })
        .collect();
    if out.is_empty() {
        out.push('_');
    }
    naming::escape(Lang::Java, &out)
}

/// Whether `s` is a valid dotted Java package name.
#[must_use]
pub fn is_package(s: &str) -> bool {
    !s.is_empty()
        && s.split('.').all(|seg| {
            let mut chars = seg.chars();
            chars
                .next()
                .is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
                && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
                && naming::escape(Lang::Java, seg) == seg
        })
}

fn html_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '\\' => out.push_str("&#92;"),
            ' '..='~' => out.push(c),
            c => out.push_str(&format!("&#x{:x};", c as u32)),
        }
    }
    out.replace("*/", "*&#47;")
}

/// One line of Javadoc text: HTML-escaped, and never starting a block tag by accident.
fn doc_line(line: &str) -> String {
    let escaped = html_escape(line.trim_end());
    match escaped.strip_prefix('@') {
        Some(rest) => format!("&#64;{rest}"),
        None => escaped,
    }
}

/// Writes a Javadoc block for `docs`, `@param` lines and a deprecation notice, or nothing.
pub fn doc_comment(
    w: &mut CodeWriter,
    docs: Option<&str>,
    params: &[(String, String)],
    deprecated: Option<&str>,
) {
    let mut lines: Vec<String> = docs
        .map(|d| d.trim().lines().map(doc_line).collect())
        .unwrap_or_default();
    let mut tags: Vec<String> = params
        .iter()
        .map(|(n, d)| format!("@param {n} {}", doc_line(d)))
        .collect();
    if let Some(msg) = deprecated {
        tags.push(if msg.is_empty() {
            "@deprecated".to_string()
        } else {
            format!("@deprecated {}", doc_line(msg))
        });
    }
    if !lines.is_empty() && !tags.is_empty() {
        lines.push(String::new());
    }
    lines.extend(tags);
    match lines.as_slice() {
        [] => {}
        [one] => {
            w.line(format!("/** {one} */"));
        }
        many => {
            w.line("/**");
            for l in many {
                w.line(if l.is_empty() {
                    " *".to_string()
                } else {
                    format!(" * {l}")
                });
            }
            w.line(" */");
        }
    }
}

/// Writes `head(` and indents by two levels, the Java continuation indent; pair with [`end_call`].
pub fn open_call(w: &mut CodeWriter, head: impl AsRef<str>) {
    w.open_with(head, "(");
    w.indent();
}

/// Ends a block opened with [`open_call`]; the caller has written the closing `)` already.
pub fn end_call(w: &mut CodeWriter) {
    w.dedent();
    w.dedent();
}

/// `@Deprecated` when a declaration is deprecated.
pub fn deprecated_annotation(w: &mut CodeWriter, deprecated: Option<&str>) {
    if deprecated.is_some() {
        w.line("@Deprecated");
    }
}

/// Adds a generated file, mapping a path error to a generation diagnostic.
pub fn add_file(
    files: &mut FileSet,
    path: &str,
    content: String,
) -> Result<(), Vec<GenDiagnostic>> {
    files.add(path, content).map_err(|e| {
        vec![GenDiagnostic::new(
            "E0805",
            format!("cannot add generated file: {e}"),
        )]
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn quotes_strings_without_depending_on_the_encoding() {
        assert_eq!(java_str("a\"b\\c\n"), "\"a\\\"b\\\\c\\n\"");
        assert_eq!(java_str("é😀"), "\"\\u00e9\\ud83d\\ude00\"");
    }

    #[test]
    fn identifiers_avoid_reserved_words_and_object_methods() {
        assert_eq!(member_ident("class"), "class_");
        assert_eq!(member_ident("order_item"), "orderItem");
        assert_eq!(member_ident("hashCode"), "hashCode_");
        assert_eq!(member_ident("toWire"), "toWire_");
        assert_eq!(
            unique(vec!["a".into(), "a".into(), "a_".into()]),
            ["a", "a_", "a__"]
        );
    }

    #[test]
    fn package_names_are_checked() {
        assert!(is_package("dev.veld.generated.shop"));
        assert!(!is_package("dev.class.x"));
        assert!(!is_package("a..b"));
        assert!(!is_package("1a"));
        assert_eq!(segment("@acme/billing"), "_acme_billing");
        assert_eq!(segment("new"), "new_");
    }

    #[test]
    fn doc_blocks_are_escaped() {
        let mut w = CodeWriter::new();
        doc_comment(&mut w, Some("One."), &[], None);
        doc_comment(
            &mut w,
            Some("a <b> */\n@see c\\d"),
            &[("x".into(), "the x".into())],
            Some("use y"),
        );
        assert_eq!(
            w.finish(),
            "/** One. */\n/**\n * a &lt;b&gt; *&#47;\n * &#64;see c&#92;d\n *\n * @param x the x\n * @deprecated use y\n */\n"
        );
    }
}
